// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzz the caller address and a future timestamp delta to drive block.timestamp
    function testFuzz_property(address caller, uint64 dt) public {
        // Keep caller non-zero EOA and dt small-ish to keep domain wide but practical
        vm.assume(caller != address(0));

        // We will set pastBlockTime to current block.timestamp by making a first call that succeeds.
        // The contract constructor funded it with 10 ether; performing a valid fallback call with 10 ether
        // at a strictly greater timestamp than default pastBlockTime will set pastBlockTime.

        // Advance time by 1 so first call is strictly greater than initial pastBlockTime (which is 0)
        vm.warp(block.timestamp + 1);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        // call fallback: need to use low-level call because fallback has no name; use address(c).call
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        // first call must succeed on the reference contract: require(msg.value==10 ether) and timestamp > 0
        assertTrue(ok1);

        // read stored pastBlockTime after successful call
        uint256 tStored = c.pastBlockTime();

        // Now drive timestamp to be exactly equal to stored pastBlockTime by warping
        // Use the fuzzed dt to optionally increase block time; but we specifically want an equality case
        // We'll set block.timestamp = tStored (dt ignored) to test the critical equality case
        vm.warp(uint256(tStored));

        // Prepare caller balance and perform the equality-timestamp call which SHOULD REVERT on reference
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        bool ok2;
        (ok2, ) = address(c).call{value: 10 ether}("");

        // GENERAL RULE (assertion): On the correct contract, a fallback call supplying exactly 10 ether
        // at block.timestamp equal to pastBlockTime MUST revert, so ok2 must be false.
        // The mutant that assigns pastBlockTime before the require will allow ok2 == true for this input,
        // so this assertion distinguishes them.
        assertTrue(!ok2);
    }
}

